begin;set search_path to public,extensions;select plan(19);
insert into auth.users(id,email) values('40000000-0000-4000-8000-000000000001','sql-review@example.test');
set local role anon;
select throws_ok($$select create_review('{}')$$,'42501',null,'Anonymous publication denied');
select throws_ok($$select get_my_reviews()$$,'42501',null,'Anonymous private reviews denied');
set local role authenticated;select set_config('request.jwt.claim.sub','40000000-0000-4000-8000-000000000001',true);
select is(create_review('{"property":"20000000-0000-4000-8000-000000000001","start":"2024-01-01","end":"2024-12-01","current":false,"paid":15000,"propertyRating":4,"managerRating":2,"body":"Synthetic review SQL fixture.","synthetic":true}')->>'status','created','Review created');
select is(jsonb_array_length(get_my_reviews()),1,'Own dashboard contains review');
select is((select landlord_id::text from get_review_feed('20000000-0000-4000-8000-000000000001') where body='Synthetic review SQL fixture.'),'10000000-0000-4000-8000-000000000004','Historic manager preserved');
select throws_ok($$select tenancy_id from reviews$$,'42501',null,'Private tenancy reference excluded');
select throws_ok($$select * from private.review_answers$$,'42501',null,'Private gender answers denied');
select throws_ok($$update reviews set body='Hacked'$$,'42501',null,'Direct updates denied');
select throws_ok($$select register_review_photo('40000000-0000-4000-8000-000000000001',gen_random_uuid(),gen_random_uuid())$$,'42501',null,'Media registration cannot bypass validation');
select lives_ok($$select delete_review((get_my_reviews()->0->>'id')::uuid)$$,'Author soft delete');
select is((select count(*)::int from get_review_feed('20000000-0000-4000-8000-000000000001') where body='Synthetic review SQL fixture.'),0,'Deleted excluded from feed');
select is((select count(*)::int from property_scores where property_id='20000000-0000-4000-8000-000000000001'),0,'No rating is no row, not zero');
reset role;
select throws_ok($$insert into private.tenancies(user_id,property_id,start_date,is_current,rent_paid) values('40000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','2024-01-01',true,15000)$$,'23505',null,'Canonical tenancy unique constraint independent of RPC');
select throws_ok($$insert into public.reviews(tenancy_id,profile_id,property_id,property_rating,body) select tenancy_id,profile_id,property_id,4,'Another fictional review' from public.reviews where body='Synthetic review SQL fixture.'$$,'23505',null,'One review per tenancy database key');
select throws_ok($$insert into private.tenancies(user_id,property_id,start_date,is_current,rent_paid) values('40000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','2023-01-01',false,15000)$$,'23514',null,'Former tenancy requires non-null end independently');
select throws_ok($$insert into private.tenancies(user_id,property_id,start_date,is_current,rent_paid) values('40000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','2099-01-01',true,15000)$$,'23514',null,'Future tenancy denied independently');
update public.management_associations set landlord_id='10000000-0000-4000-8000-000000000001' where property_id='20000000-0000-4000-8000-000000000001' and start_date='2020-01-01';
select is((select landlord_id::text from public.reviews where body='Synthetic review SQL fixture.'),'10000000-0000-4000-8000-000000000004','Correcting management history never reassigns historic review');
insert into private.property_contributors(property_id,user_id,declared_owner) values('20000000-0000-4000-8000-000000000008','40000000-0000-4000-8000-000000000001',true);
set local role authenticated;
select throws_ok($$select create_review('{"property":"20000000-0000-4000-8000-000000000008","start":"2025-01-01","current":true,"paid":15000,"propertyRating":4,"body":"Synthetic owned property review.","synthetic":true}')$$,'42501',null,'Own property reviews forbidden');
select throws_ok($$select update_tenancy((get_my_reviews()->0->>'id')::uuid,true,'2024-12-01',15000)$$,'P0001',null,'Current tenancy cannot include end date');
select * from finish();rollback;
